import React, { useCallback, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Button,
  Input,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  LinPageLayout,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { analyticsService } from '../../../services/analytics/analyticsService';
import type { AccountActivityAllRow } from '../../../services/analytics/models';
import { formatDate, formatVnd } from '../../../utils/formatters';
import { exportExcel, monthStartEnd } from '../../../utils/exportExcel';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { navigateInAppPath } from '../../../router/navigateInAppPath';
import erp from '../../../styles/erpPage.module.css';
import reportStyles from '../../../styles/erpReportPage.module.css';
import styles from './SoTongHopChuTTatCaTkPage.module.css';

const TEST_ID = 'rpt-so-tong-hop-chu-t-tat-ca-tk';
const PAGE_ID = 'baocao-so-tong-hop-chu-t-tat-ca-tk';
const TITLE = 'Sổ tổng hợp chữ T của một tài khoản (Tất cả các tài khoản)';

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function accountDisplay(row: AccountActivityAllRow): string {
  if (row.accountCodeDisplay != null && row.accountCodeDisplay !== '') {
    return row.accountCodeDisplay;
  }
  const code = row.accountCode ?? '';
  const level = Number(row.bacTk ?? 1);
  const indent = Math.max(0, level - 1);
  return '\u00A0'.repeat(3 * indent) + code;
}

function normalizeItems(items: AccountActivityAllRow[]): AccountActivityAllRow[] {
  return items.map(r => ({
    ...r,
    accountCode: r.accountCode ?? '',
    openingBalance: Number(r.openingBalance ?? 0),
    periodDebit: Number(r.periodDebit ?? 0),
    periodCredit: Number(r.periodCredit ?? 0),
    closingBalance: Number(r.closingBalance ?? 0),
    openingSide: r.openingSide === 'C' ? 'C' : 'N',
    closingSide: r.closingSide === 'C' ? 'C' : 'N',
    isParent: Boolean(r.isParent),
    bacTk: Number(r.bacTk ?? 1),
  }));
}

const SoTongHopChuTTatCaTkPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const initial = monthStartEnd();

  const [accountCode, setAccountCode] = useState('');
  const [fromDate, setFromDate] = useState(initial.fromDate);
  const [toDate, setToDate] = useState(initial.toDate);

  const [items, setItems] = useState<AccountActivityAllRow[]>([]);
  const [summaryDebit, setSummaryDebit] = useState(0);
  const [summaryCredit, setSummaryCredit] = useState(0);
  const [appliedFrom, setAppliedFrom] = useState('');
  const [appliedTo, setAppliedTo] = useState('');
  const [appliedAccount, setAppliedAccount] = useState('');
  const [hasViewed, setHasViewed] = useState(false);
  const [loading, setLoading] = useState(false);
  const [filterError, setFilterError] = useState('');
  const { showTableLoading } = useCatalogTableBusy(loading);

  const handleView = useCallback(() => {
    setFilterError('');
    const company = sessionCompany();
    if (!company) {
      setFilterError('Không xác định đơn vị');
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return;
    }
    if (!fromDate.trim() || !toDate.trim()) {
      setFilterError('Chọn khoảng ngày');
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return;
    }
    if (toDate < fromDate) {
      setFilterError('Đến ngày phải ≥ Từ ngày');
      dispatchAppToast(dispatch, { message: 'Đến ngày phải ≥ Từ ngày', type: 'error' });
      return;
    }

    const acct = accountCode.trim();
    // Optional TK — cấm silent 111; omit empty from query.
    // Cấm gửi loaiBc / loaiSo / cpName / reportKind (wrapper identity = page).
    const params: Record<string, string | number | undefined> = {
      fromDate: fromDate.trim(),
      toDate: toDate.trim(),
      pageSize: 0,
    };
    if (acct) params.accountCode = acct;

    setLoading(true);
    analyticsService
      .getAccountActivityAll(params)
      .then(report => {
        setItems(normalizeItems(report.items ?? []));
        setSummaryDebit(Number(report.summary?.totalPeriodDebit ?? 0));
        setSummaryCredit(Number(report.summary?.totalPeriodCredit ?? 0));
        setAppliedFrom(fromDate.trim());
        setAppliedTo(toDate.trim());
        setAppliedAccount(acct);
        setHasViewed(true);
      })
      .catch(err => {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không tải được sổ tổng hợp chữ T tất cả tài khoản'),
          type: 'error',
        });
      })
      .finally(() => setLoading(false));
  }, [accountCode, dispatch, fromDate, toDate]);

  const onEnterView = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleView();
      }
    },
    [handleView],
  );

  const handleExport = useCallback(() => {
    if (!hasViewed || loading) return;
    const prefix = appliedAccount ? `_${appliedAccount}` : '';
    const fileName = `so-tong-hop-chu-t-tat-ca-tk_${appliedFrom}_${appliedTo}${prefix}.xlsx`;
    const params: Record<string, string | number | undefined> = {
      fromDate: appliedFrom,
      toDate: appliedTo,
      pageSize: 0,
    };
    if (appliedAccount) params.accountCode = appliedAccount;
    void exportExcel('/accounting/account-activity-all/export-excel', params, fileName).catch(() => {
      /* toast already in exportExcel */
    });
  }, [appliedAccount, appliedFrom, appliedTo, hasViewed, loading]);

  const handlePrint = useCallback(() => {
    window.print();
  }, []);

  const handleRefresh = useCallback(() => {
    const next = monthStartEnd();
    setAccountCode('');
    setFromDate(next.fromDate);
    setToDate(next.toDate);
    setFilterError('');
    setHasViewed(false);
    setItems([]);
    setAppliedAccount('');
    setAppliedFrom('');
    setAppliedTo('');
    setSummaryDebit(0);
    setSummaryCredit(0);
  }, []);

  /** Drill → sổ chữ T một TK (CP_GLTH1). Allow parent. Cấm so-chi-tiet. */
  const drillToTForm = useCallback(
    (row: AccountActivityAllRow) => {
      if (!hasViewed || !appliedFrom || !appliedTo || !row.accountCode) return;
      const qs = new URLSearchParams({
        accountCode: row.accountCode,
        fromDate: appliedFrom,
        toDate: appliedTo,
      });
      navigateInAppPath(`/baocao/so-tong-hop-chu-t?${qs.toString()}`, navigate);
    },
    [appliedFrom, appliedTo, hasViewed, navigate],
  );

  const exportDisabled = !hasViewed || loading;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        label: 'Làm mới',
        variant: 'secondary',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: loading,
        onClick: handleRefresh,
      },
      {
        id: 'exportExcel',
        action: 'exportExcel',
        placement: 'right',
        label: 'Xuất Excel',
        variant: 'secondary',
        testId: `${TEST_ID}-export-excel`,
        disabled: exportDisabled,
        onClick: handleExport,
      },
      {
        id: 'exportPrint',
        action: 'print',
        placement: 'right',
        label: 'In',
        variant: 'secondary',
        testId: `${TEST_ID}-export-print`,
        disabled: exportDisabled,
        onClick: handlePrint,
      },
    ],
    [exportDisabled, handleExport, handlePrint, handleRefresh, loading],
  );

  const subtitle =
    hasViewed && appliedFrom && appliedTo
      ? `Từ: ${formatDate(appliedFrom)} đến ngày ${formatDate(appliedTo)} · ${
          appliedAccount ? `TK: ${appliedAccount}` : 'Tất cả'
        }`
      : undefined;

  const listBody = showTableLoading ? null : (
    <div className={erp.tableWrapper}>
      {subtitle ? (
        <div data-testid={`${TEST_ID}-subtitle`} className={reportStyles.subtitle} style={{ marginBottom: '0.5rem' }}>
          {subtitle}
        </div>
      ) : null}
      {!hasViewed ? (
        <div className={styles.hintBeforeView} data-testid={`${TEST_ID}-hint`}>
          Chọn khoảng ngày (và tùy chọn prefix tài khoản) rồi bấm Xem
        </div>
      ) : null}
      <table className={reportStyles.table} data-testid={`${TEST_ID}-grid`}>
        <thead>
          <tr>
            <th>Tài khoản</th>
            <th>Tên tài khoản</th>
            <th className={reportStyles.colRight}>Dư đầu</th>
            <th className={styles.cellSide}>N/C</th>
            <th className={reportStyles.colRight}>PS nợ</th>
            <th className={reportStyles.colRight}>PS có</th>
            <th className={reportStyles.colRight}>Dư cuối</th>
            <th className={styles.cellSide}>N/C</th>
          </tr>
        </thead>
        <tbody>
          {!hasViewed
            ? null
            : items.map((row, index) => {
                const isParent = Boolean(row.isParent);
                return (
                  <tr
                    key={`${row.accountCode}|${isParent ? 'P' : 'L'}|${index}`}
                    className={isParent ? styles.rowParent : undefined}
                    data-testid={`${TEST_ID}-row-${index}`}
                    data-is-parent={isParent ? '1' : '0'}
                    data-account-code={row.accountCode}
                    onDoubleClick={() => drillToTForm(row)}
                    style={{ cursor: 'pointer' }}
                    title="Double-click để mở sổ tổng hợp chữ T"
                  >
                    <td className={styles.cellIndent}>{accountDisplay(row)}</td>
                    <td>{row.accountName ?? ''}</td>
                    <td className={reportStyles.colRight}>{formatVnd(row.openingBalance)}</td>
                    <td className={styles.cellSide}>{row.openingSide ?? 'N'}</td>
                    <td className={reportStyles.colRight}>{formatVnd(row.periodDebit)}</td>
                    <td className={reportStyles.colRight}>{formatVnd(row.periodCredit)}</td>
                    <td className={reportStyles.colRight}>{formatVnd(row.closingBalance)}</td>
                    <td className={styles.cellSide}>{row.closingSide ?? 'N'}</td>
                  </tr>
                );
              })}
        </tbody>
      </table>
      {hasViewed && items.length === 0 ? (
        <div className={erp.empty} data-testid={`${TEST_ID}-empty`}>
          Không có dữ liệu
        </div>
      ) : null}
      {hasViewed && items.length > 0 ? (
        <div className={styles.summaryBar} data-testid={`${TEST_ID}-summary`} style={{ marginTop: '0.75rem' }}>
          <span>Tổng PS nợ: {formatVnd(summaryDebit)}</span>
          <span>Tổng PS có: {formatVnd(summaryCredit)}</span>
        </div>
      ) : null}
    </div>
  );

  const footer = null;

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-report-list-page
      data-testid={`${TEST_ID}-list`}
    >
      <LinPageLayout
        kind="report"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{ title: TITLE, titleIconClass: 'fas fa-book' }}
        listTitle={TITLE}
        filterMaxWidthPx={1200}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'report',
          actions: toolbarActions,
        }}
        footer={footer}
        filters={
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem', alignItems: 'flex-end' }}>
            <div data-testid={`${TEST_ID}-field-fromDate`}>
              <label htmlFor={`${TEST_ID}-field-fromDate-input`}>Từ ngày</label>
              <Input
                id={`${TEST_ID}-field-fromDate-input`}
                data-testid={`${TEST_ID}-field-fromDate-input`}
                type="date"
                value={fromDate}
                onChange={e => setFromDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-toDate`}>
              <label htmlFor={`${TEST_ID}-field-toDate-input`}>Đến ngày</label>
              <Input
                id={`${TEST_ID}-field-toDate-input`}
                data-testid={`${TEST_ID}-field-toDate-input`}
                type="date"
                value={toDate}
                onChange={e => setToDate(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <div data-testid={`${TEST_ID}-field-accountCode`}>
              <label htmlFor={`${TEST_ID}-field-accountCode-input`}>Tài khoản</label>
              <Input
                id={`${TEST_ID}-field-accountCode-input`}
                data-testid={`${TEST_ID}-field-accountCode-input`}
                value={accountCode}
                placeholder="Mã TK (để trống = tất cả)"
                onChange={e => setAccountCode(e.target.value)}
                onKeyDown={onEnterView}
              />
            </div>
            <Button
              variant="primary"
              data-testid={`${TEST_ID}-view-btn`}
              disabled={loading}
              onClick={handleView}
            >
              Xem
            </Button>
            {filterError ? (
              <div className={styles.filterError} data-testid={`${TEST_ID}-filter-error`}>
                {filterError}
              </div>
            ) : null}
          </div>
        }
      >
        {listBody}
      </LinPageLayout>
    </div>
  );
};

export default SoTongHopChuTTatCaTkPage;
